// Differential checks of TcoAck-faithful.js against Lean, generated by leanscript --check
import * as M from "./TcoAck-faithful.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("ack2(0n, 0n)", () => M.ack2(0n, 0n), "1", false);
check("ack2(0n, 2n)", () => M.ack2(0n, 2n), "3", false);
check("ack2(1n, 1n)", () => M.ack2(1n, 1n), "3", false);
check("ack2(2n, 0n)", () => M.ack2(2n, 0n), "3", false);
check("ack2(0n, 13n)", () => M.ack2(0n, 13n), "14", false);
check("ack2(1n, 5n)", () => M.ack2(1n, 5n), "7", false);
check("ack2(2n, 2n)", () => M.ack2(2n, 2n), "7", false);
check("AckWithoutStackButUsingCantorPairing$pair(0n, 0n)", () => M.AckWithoutStackButUsingCantorPairing$pair(0n, 0n), "0", false);
check("AckWithoutStackButUsingCantorPairing$pair(0n, 2n)", () => M.AckWithoutStackButUsingCantorPairing$pair(0n, 2n), "5", false);
check("AckWithoutStackButUsingCantorPairing$pair(1n, 1n)", () => M.AckWithoutStackButUsingCantorPairing$pair(1n, 1n), "4", false);
check("AckWithoutStackButUsingCantorPairing$pair(2n, 0n)", () => M.AckWithoutStackButUsingCantorPairing$pair(2n, 0n), "3", false);
check("AckWithoutStackButUsingCantorPairing$pair(0n, 13n)", () => M.AckWithoutStackButUsingCantorPairing$pair(0n, 13n), "104", false);
check("AckWithoutStackButUsingCantorPairing$pair(1n, 5n)", () => M.AckWithoutStackButUsingCantorPairing$pair(1n, 5n), "26", false);
check("AckWithoutStackButUsingCantorPairing$pair(2n, 2n)", () => M.AckWithoutStackButUsingCantorPairing$pair(2n, 2n), "12", false);
check("AckWithoutStackButUsingCantorPairing$pair(5n, 1n)", () => M.AckWithoutStackButUsingCantorPairing$pair(5n, 1n), "22", false);
check("AckWithoutStackButUsingCantorPairing$pair(13n, 0n)", () => M.AckWithoutStackButUsingCantorPairing$pair(13n, 0n), "91", false);
check("AckWithoutStackButUsingCantorPairing$pair(2n, 13n)", () => M.AckWithoutStackButUsingCantorPairing$pair(2n, 13n), "133", false);
check("AckWithoutStackButUsingCantorPairing$pair(5n, 5n)", () => M.AckWithoutStackButUsingCantorPairing$pair(5n, 5n), "60", false);
check("AckWithoutStackButUsingCantorPairing$pair(13n, 2n)", () => M.AckWithoutStackButUsingCantorPairing$pair(13n, 2n), "122", false);
check("AckWithoutStackButUsingCantorPairing$pair(13n, 13n)", () => M.AckWithoutStackButUsingCantorPairing$pair(13n, 13n), "364", false);

console.log(`TcoAck-faithful.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
